```java
int[][] m = {{6, 5, 3}, {1, 5, 1}, {5, 2, 2}, {3, 6, 3}};
int bestSum = 0;
int bestRow = 0;
for (int r = 0; r < m.length; r++) {
    int sum = 0;
    for (int c = 0; c < m[r].length; c++) {
        sum += m[r][c];
    }
    if (sum > bestSum) {
        bestSum = sum;
        bestRow = r;
    }
}
System.out.println(bestRow + " " + bestSum);
```

